import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {Array<{text:string,role?:string,typography?:{fontSize?:number}}>} [textContent]
 * @property {Array<{name:string,params:Object,trigger:string}>} [cinematicPrimitives]
 * @property {Object} [intent]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {Object} textureLoader
 * @property {Object} fontAtlas
 * @property {Object} primitives
 * @property {Function} emit
 * @property {string} [tier]
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh, Color } = ctx.THREE;

  // Root container
  const root = new Group();
  root.userData.handlers = {};

  // Load texture (if any)
  const texturePromise = config.imageUrl
    ? ctx.textureLoader.loadTexture(config.imageUrl)
    : Promise.resolve(null);

  // Create plane geometry (default 1x1, can be scaled later by parent)
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({ toneMapped: true });

  const plane = new Mesh(geometry, material);
  plane.renderOrder = 0;
  root.add(plane);

  // Apply texture when loaded
  texturePromise.then((tex) => {
    if (tex) {
      material.map = tex;
      material.needsUpdate = true;
    }
  });

  // Add textual content
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const opts = {
      fontSize: item.typography?.fontSize ?? 39,
      color: config.intent?.visualSpec?.colors?.ink ?? '#16161d',
      align: 'center',
    };
    const txt = ctx.fontAtlas.createText(item.text, opts);
    // Position text slightly above plane to avoid z‑fighting
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  // Apply cinematic primitives (if any)
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const handler = ctx.primitives[prim.name](root, prim.params);
      primitiveHandles.push(handler);
    }
  }

  // Entrance animation (rise‑in)
  const entranceTL = gsap.timeline({ paused: true });
  entranceTL.from(
    root.position,
    { y: 0.4, duration: 0.7, ease: 'power3.out' }
  );
  entranceTL.from(
    root.scale,
    { x: 0.8, y: 0.8, z: 0.8, duration: 0.5, ease: 'power2.out' },
    '-=0.5'
  );
  entranceTL.play();

  // Cleanup routine
  root.userData.cleanup = () => {
    // Stop GSAP timelines
    entranceTL.kill();

    // Dispose primitives
    for (const ph of primitiveHandles) {
      if (ph && typeof ph.cleanup === 'function') ph.cleanup();
    }

    // Dispose material and geometry
    material.dispose();
    geometry.dispose();

    // Dispose texture if it was loaded
    if (material.map && material.map.dispose) {
      material.map.dispose();
    }

    // Remove all children
    root.traverse((obj) => {
      if (obj !== root && obj.parent) {
        obj.parent.remove(obj);
      }
    });
  };

  return root;
}
